1	package renamecheck
2	
3	import (
4		"bufio"
5		"fmt"
6		"io"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"regexp"
11		"sort"
12		"strings"
13	)
14	
15	type Finding struct {
16		Path    string
17		Line    int
18		Column  int
19		Surface string
20		Match   string
21	}
22	
23	type Options struct {
24		Root string
25		Out  io.Writer
26	}
27	
28	type rule struct {
29		surface string
30		re      *regexp.Regexp
31		rootGo  bool
32	}
33	
34	var rules = []rule{
35		{surface: "github.com/DocumentDrivenDX/agent", re: regexp.MustCompile(regexp.QuoteMeta("github.com/DocumentDrivenDX/agent"))},
36		{surface: "root package agent", re: regexp.MustCompile(`^\s*package\s+agent\s*$`), rootGo: true},
37		{surface: "ddx-agent", re: regexp.MustCompile(regexp.QuoteMeta("ddx-agent"))},
38		{surface: "DDX Agent/DDx Agent", re: regexp.MustCompile(`DD[Xx] Agent`)},
39		{surface: ".agent", re: regexp.MustCompile(`(^|[^A-Za-z0-9_])\.agent([^A-Za-z0-9_]|$)`)},
40		{surface: "~/.config/agent", re: regexp.MustCompile(regexp.QuoteMeta("~/.config/agent"))},
41		{surface: "AGENT_*/DDX_AGENT_*", re: regexp.MustCompile(`\b(?:DDX_AGENT|AGENT)_[A-Z0-9_]+\b`)},
42	}
43	
44	var skippedDirs = map[string]bool{
45		".git":                 true,
46		".ddx":                 true,
47		".agents":              true,
48		".claude":              true,
49		".helix-ratchets":      true,
50		"docs/helix":           true,
51		"docs/research":        true,
52		"internal/renamecheck": true,
53		// DDX_AGENT_* harness env vars are not yet renamed; allowlisted until a
54		// dedicated harness-rename bead updates them.
55		"internal/harnesses": true,
56	}
57	
58	var skippedFiles = map[string]bool{
59		"CHANGELOG.md": true,
60		// Historical benchmark subset v1 is a documented placeholder artifact retained
61		// per CL-004.09 / docs/research/scripts-fixtures-assets-cleanup-inventory-2026-04-30.md.
62		// Its header comment preserves the original creation date and old product name as
63		// historical evidence; no active code generates or consumes the product-name string.
64		"scripts/benchmark/task-subset-v1.yaml": true,
65		// Root-level service test files that reference DDX_AGENT_* harness env vars
