74	func Scan(opts Options) ([]Finding, error) {
75		root := opts.Root
76		if root == "" {
77			root = "."
78		}
79	
80		var findings []Finding
81		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
82			if err != nil {
83				return err
84			}
85			rel, err := filepath.Rel(root, path)
86			if err != nil {
87				return err
88			}
89			rel = filepath.ToSlash(rel)
90			if rel == "." {
91				return nil
92			}
93			if d.IsDir() {
94				if shouldSkipDir(rel) {
95					return filepath.SkipDir
96				}
97				return nil
98			}
99			if skippedFiles[rel] {
100				return nil
101			}
102			if !isTextCandidate(rel) {
103				return nil
104			}
105			fileFindings, err := scanFile(root, rel)
106			if err != nil {
107				return err
108			}
109			findings = append(findings, fileFindings...)
110			return nil
111		})
112		if err != nil {
113			return nil, err
114		}
115		sort.Slice(findings, func(i, j int) bool {
116			if findings[i].Path != findings[j].Path {
117				return findings[i].Path < findings[j].Path
118			}
119			if findings[i].Line != findings[j].Line {
120				return findings[i].Line < findings[j].Line
121			}
122			return findings[i].Column < findings[j].Column
123		})
124		return findings, nil
125	}
126	
127	func Report(w io.Writer, findings []Finding) error {
128		if w == nil {
129			return nil
130		}
131		if len(findings) == 0 {
132			_, err := fmt.Fprintln(w, "rename-noise: no unallowlisted old-name hits found")
133			return err
134		}
135		if _, err := fmt.Fprintf(w, "rename-noise: %d unallowlisted old-name hit(s)\n", len(findings)); err != nil {
136			return err
137		}
138		for _, f := range findings {
139			if _, err := fmt.Fprintf(w, "%s:%d:%d: %s: %q\n", f.Path, f.Line, f.Column, f.Surface, f.Match); err != nil {
140				return err
141			}
142		}
143		return nil
144	}
145	
146	func Run(opts Options) ([]Finding, error) {
147		findings, err := Scan(opts)
148		if err != nil {
149			return nil, err
150		}
151		return findings, Report(opts.Out, findings)
152	}
153	
154	func scanFile(root, rel string) ([]Finding, error) {
155		file, err := os.Open(filepath.Join(root, filepath.FromSlash(rel)))
156		if err != nil {
157			return nil, err
158		}
159		defer file.Close()
160	
161		var findings []Finding
162		scanner := bufio.NewScanner(file)
163		buf := make([]byte, 0, 64*1024)
164		scanner.Buffer(buf, 1024*1024)
165		lineNo := 0
166		for scanner.Scan() {
167			lineNo++
168			line := scanner.Text()
169			for _, r := range rules {
170				if r.rootGo && !isRootGoFile(rel) {
171					continue
172				}
173				loc := r.re.FindStringIndex(line)
174				if loc == nil {
175					continue
176				}
177				findings = append(findings, Finding{
178					Path:    rel,
179					Line:    lineNo,
180					Column:  loc[0] + 1,
181					Surface: r.surface,
182					Match:   line[loc[0]:loc[1]],
183				})
184			}
185		}
186		return findings, scanner.Err()
187	}
188	
189	func shouldSkipDir(rel string) bool {
190		if skippedDirs[rel] {
191			return true
192		}
193		for dir := range skippedDirs {
194			if strings.HasPrefix(rel, dir+"/") {
195				return true
196			}
197		}
198		return false
199	}
200	
201	func isRootGoFile(rel string) bool {
202		return filepath.Dir(rel) == "." && strings.HasSuffix(rel, ".go")
203	}
204	
205	func isTextCandidate(rel string) bool {
206		base := filepath.Base(rel)
207		if strings.HasPrefix(base, ".") && base != ".env" {
208			return false
209		}
210		switch filepath.Ext(rel) {
211		case ".go", ".md", ".txt", ".yaml", ".yml", ".json", ".jsonl", ".toml", ".sh", ".py", ".env":
212			return true
213		default:
214			return base == "Makefile" || base == "Dockerfile" || base == "go.mod"
215		}
216	}
